import unittest,re
from tools.kjv_archive import load_register,read
class RevelationSealedTribesTests(unittest.TestCase):
 def test_sealed_tribes_and_trumpets(self):
  prior,_=load_register('0.10-kjv.272');lang,manifest=load_register('0.10-kjv.273')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('revelation-'):c for c in read(lang.folder/'revelation-sealed-tribes-cases.json')};self.assertEqual(len(cases),51)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}-{'worship'}&set(r['keys']))
  anchors={'7:1': ['four angel:pl', 'four corner:pl', 'four wind:pl', 'nor on any kjv_tree'], '7:2': ['other angel from east up go:cv', 'live:pr god seal', 'four angel:pl'], '7:3': ['wesg ourone/god servant:pl', 'in their/forehead:pl seal:perf'], '7:4': ['all kjv_israel child:pl kjv_tribe:pl', 'twelve+twelve+thousand'], '7:5': ['kjv_juda_hebrews kjv_tribe twelve+thousand', 'kjv_reuben kjv_tribe twelve+thousand', 'kjv_gad kjv_tribe twelve+thousand'], '7:6': ['kjv_aser_luke kjv_tribe twelve+thousand', 'kjv_nephthalim kjv_tribe twelve+thousand', 'kjv_manasses_tribe_revelation kjv_tribe twelve+thousand'], '7:7': ['kjv_simeon kjv_tribe twelve+thousand', 'kjv_levi kjv_tribe twelve+thousand', 'kjv_issachar kjv_tribe twelve+thousand'], '7:8': ['kjv_zabulon kjv_tribe twelve+thousand', 'kjv_joseph kjv_tribe twelve+thousand', 'kjv_benjamin kjv_tribe twelve+thousand'], '7:9': ['no man kjv_number:inf able be:pa', 'nation:pl and kjv_family:pl and people and tongue:pl', 'white kjv_robe:pl', 'kjv_palm_tree:pl'], '7:10': ['ourone/god who upon throne', 'and to kjv_lamb'], '7:11': ['four beast:pl', 'their/face:pl fall:pa', 'god kjv_worship:pa'], '7:12': ['amen blessing and glory and wisdom and thanks and honour and power and might', 'ourone/god forever and forever be:opt amen'], '7:13': ['one_num of kjv_elder:pl', 'what be:pr:q', 'from where they come:pa:q'], '7:14': ['sir thou know:pr', 'great kjv_tribulation', 'their/kjv_robe:pl wash:perf', 'in kjv_lamb blood white make:perf'], '7:15': ['in his/kjv_temple day and night', 'among they dwell:fu'], '7:16': ['no more hunger:fu', 'neither any more thirst:fu', 'neither sun on they shine:fu nor any heat'], '7:17': ['kjv_lamb who in throne middle', 'live:pr kjv_fountain:pl of water:pl', 'all tear:pl away kjv_wipe:fu'], '8:1': ['seven:ord seal', 'about half hour'], '8:2': ['seven angel:pl', 'seven trumpet:pl'], '8:3': ['gold:adj kjv_censer', 'much kjv_incense', 'all holy person:pl prayer:pl', 'gold:adj altar'], '8:4': ['kjv_incense smoke', 'with holy person:pl prayer:pl', 'out of angel hand before god'], '8:5': ['kjv_censer take:pa', 'altar fire', 'voice:pl and thunder:ev:pl and lightning:pl and earthquake'], '8:6': ['seven angel:pl who seven trumpet:pl', 'themselves to sound:inf prepare:pa'], '8:7': ['first angel', 'hail and fire with blood mix:psv:pp', 'kjv_tree:pl kjv_third_share', 'all green grass'], '8:8': ['second angel', 'as great mountain', 'sea kjv_third_share blood'], '8:9': ['creature:pl which in sea', 'life have:pa kjv_third_share', 'ship:pl kjv_third_share'], '8:10': ['third angel', 'as lamp burn:cv', 'river:pl kjv_third_share', 'upon water:pl kjv_fountain:pl'], '8:11': ['kjv_wormwood_star_revelation', 'water:pl kjv_third_share kjv_wormwood', 'because bitter'], '8:12': ['fourth angel', 'sun kjv_third_share', 'moon kjv_third_share', 'star:pl kjv_third_share', 'their/kjv_third_share', 'its/kjv_third_share', 'night likewise'], '8:13': ['angel through heaven middle fly:cv', 'three angel:pl', 'woe:excl woe:excl woe:excl'], '9:1': ['five:ord angel', 'star from heaven to earth', 'kjv_bottomless_pit_revelation key'], '9:2': ['kjv_bottomless_pit_revelation open:pa', 'as great kjv_furnace smoke', 'sun and air'], '9:3': ['kjv_locust:pl', 'as earth kjv_scorpion:pl power'], '9:4': ['grass neither any green thing neither any kjv_tree', 'only those man:pl', 'god seal have:neg:pr'], '9:5': ['kill:neg:should', 'five month:pl torment:psv:should', 'kjv_scorpion torment'], '9:6': ['death seek:fu', 'it find:neg:fu', 'die:inf desire:fu', 'death from they flee:fu'], '9:7': ['shape:pl like to battle prepare:psv:pp horse:pl', 'as crown:pl like gold', 'face:pl as man:pl face:pl'], '9:8': ['hair as woman:pl hair', 'tooth:pl as lion:pl tooth:pl'], '9:9': ['kjv_breastplate_armour:pl as iron kjv_breastplate_armour:pl', 'their/wing:pl sound', 'many horse:pl chariot:pl'], '9:10': ['tail:pl like to kjv_scorpion:pl', 'in their/tail:pl sting:pl', 'five month:pl hurt:inf'], '9:11': ['king have:pa who kjv_bottomless_pit_revelation angel', 'kjv_hebrew tongue kjv_abaddon_revelation', 'greek tongue his/name kjv_apollyon_revelation'], '9:12': ['one_num woe pass:perf', 'two woe:du'], '9:13': ['six:ord angel', 'four horn:pl', 'gold:adj altar'], '9:14': ['six:ord angel', 'four angel:pl', 'great river kjv_euphrates'], '9:15': ['four angel:pl', 'one_num hour and one_num day and one_num month and one_num year', 'man:pl kjv_third_share slay:inf'], '9:16': ['two+hundred+thousand+thousand', 'i their/kjv_number:ev hear:pa'], '9:17': ['fire and kjv_jacinth_revelation and kjv_brimstone kjv_breastplate_armour:pl', 'head:pl as lion:pl head:pl', 'fire and smoke and kjv_brimstone issue:pa'], '9:18': ['these three man:pl kjv_third_share', 'by fire and by smoke and by kjv_brimstone'], '9:19': ['their/power in their/mouth and in their/tail:pl', 'like to serpent:pl', 'head:pl have:pa'], '9:20': ['remainder', 'gold and silver and kjv_brass and stone and wood idol:pl', 'neither see:can nor hear:can nor walk:can'], '9:21': ['murder:ev:pl', 'kjv_sorcery:pl', 'kjv_fornication', 'theft:pl']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('wesg ourone/god servant:pl',cases['7-3']['analysis'])
  self.assertIn('twelve+twelve+thousand',cases['7-4']['analysis'])
  for ref in ('7-5','7-6','7-7','7-8'):self.assertEqual(cases[ref]['analysis'].split().count('twelve+thousand'),3)
  self.assertIn('kjv_joseph kjv_tribe',cases['7-8']['analysis'])
  self.assertIn('in kjv_lamb blood white',cases['7-14']['analysis'])
  self.assertIn('angel through heaven',cases['8-13']['analysis'])
  self.assertEqual(cases['8-13']['analysis'].split().count('woe:excl'),3)
  self.assertIn('two woe:du',cases['9-12']['analysis'])
  self.assertIn('two+hundred+thousand+thousand',cases['9-16']['analysis'])
  self.assertIn('their/power in their/mouth and in their/tail:pl',cases['9-19']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),6)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
